import React from "react";
import { BrowserRouter as Router, Route, Switch, Redirect } from 'react-router-dom';
import Header from './Header';
import Footer from './Footer';
import Event from './Event';
import ShowServiceList from './ShowServiceList.js';
import Property from './Property';
import Ledger from './Ledger';
import AddEntry from './AddEntry';
import Bills from './Bills';
import MyEvents from './MyEvents';
import { Complaints, PostComp, ResolveComp } from './Complaints.js';
import { Housekeeping, RequestHousekeeping } from './Housekeeping.js';
import QuartersBooking from "./QuartersBooking";
import AdminFacultyBookings from './AdminFacultyBookings';

function Dashboard(props) {
  if (!props.user.username) {
    return <Redirect to="/login" />;
  }

  const { role, userid, fname, lname } = props.user;

  return (
    <Router>
      <div>
        <Header />
        <div style={{ margin: '10%' }}>
          <h1>Welcome back {fname + " " + lname}!</h1>
          <ShowServiceList role={role} />
        </div>
        <Footer />
        
        <Switch>
          <Route exact path='/dashboard'>
            <div>
              <h1>Welcome to the Dashboard</h1>
            </div>
          </Route>

          {/* Conditional Route for Faculty Booking */}
          {role === "admin" ? (
            <Route path="/dashboard/faculty-booking" component={AdminFacultyBookings} />
          ) : (
            <Route path="/dashboard/faculty-booking" render={() => <QuartersBooking user={props.user} />} />
          )}

          {/* Other Routes */}
          <Route exact path="/dashboard/event/myevents" component={MyEvents} />
          <Route exact path='/dashboard/event' component={Event} />
          <Route path='/dashboard/property' component={Property} />
          <Route exact path='/dashboard/ledger/add' component={AddEntry} />
          <Route exact path='/dashboard/ledger' component={Ledger} />
          <Route path='/dashboard/bills' component={Bills} />
          
          {/* Complaints Routes */}
          <Route path='/dashboard/complaint'>
            <Complaints role={role} id={userid} />
            <PostComp userid={userid} />
          </Route>
          <Route path='/complaint/resolve/:id' component={(props) => <ResolveComp {...props} />} />

          {/* Housekeeping Routes */}
          <Route path='/dashboard/housekeeping'>
            <Housekeeping role={role} id={userid} />
          </Route>
          <Route path='/housekeeping/request/:uid/:sid' component={(props) => <RequestHousekeeping {...props} id={userid} role={role} />} />
        </Switch>
      </div>
    </Router>
  );
}

export default Dashboard;
